def fizz_buzz() -> None:
    """
    Prints numbers from 1 to 100, replacing multiples of 3 with 'Fizz',
    multiples of 5 with 'Buzz', and multiples of both with 'FizzBuzz'.
    """
    for i in range(1, 101):
        if i % 3 == 0 and i % 5 == 0:
            print("FizzBuzz")
        elif i % 3 == 0:
            print("Fizz")
        elif i % 5 == 0:
            print("Buzz")
        else:
            print(i)

def check_key(data, target_key):
    # Check if target_key exists in the current dictionary
    if target_key in data:
        return True

    # Recursively check nested dictionaries and lists containing dictionaries
    for value in data.values():
        if isinstance(value, dict):
            if check_key(value, target_key):
                return True
        elif isinstance(value, list):
            for item in value:
                if isinstance(item, dict) and check_key(item, target_key):
                    return True

    return False

