        if n % i == 0:
            return False
    return True

def is_valid_identifier(s):
    # Check if string is a valid Python identifier
    if not s:
        return False  # Empty string is not valid
    if not s[0].isalpha() and s[0] != '_':
        return False
    for c in s[1:]:
        if not (c.isalnum() or c == '_'):
            return False
    return True

def fibonacci(n):
    if n == 0:
        return 0
    a, b = 0, 1
    for _ in range(1, n):
        a, b = b, a + b
    return b

