from typing import Dict, Any

def flatten_dict(nested_dict: Dict[str, Any]) -> Dict[str, Any]:
    """
    Flattens a nested dictionary into a single-level dictionary with dot-separated keys.

    Args:
        nested_dict: The dictionary to flatten.

    Returns:
        A flattened dictionary.

    Raises:
        TypeError: If nested_dict is not a dictionary.
    """
    if not isinstance(nested_dict, dict):
        raise TypeError("Input must be a dictionary")

    flattened: Dict[str, Any] = {}
    for key, value in nested_dict.items():
        if isinstance(value, dict):
            sub_flattened = flatten_dict(value)
            for subkey, subvalue in sub_flattened.items():
                flattened[f"{key}.{subkey}"] = subvalue
        else:
            flattened[key] = value
    return flattened

def divisors(n: int) -> dict:
    """
    Returns a dictionary where keys are divisors of n and values are the number of occurrences 
    of each divisor in the range 1 to n.

    :param n: A positive integer.
    :return: A dictionary mapping divisors to their occurrence counts.
    """
    divisors_dict = {}
    for i in range(1, n + 1):
        if n % i == 0:
            divisors_dict[i] = n // i
    return divisors_dict

def generate_subsets(nums):
    subsets = []
    def backtrack(start, current):
        subsets.append(current[:])
        for i in range(start, len(nums)):
            current.append(nums[i])
            backtrack(i + 1, current)
            current.pop()
    backtrack(0, [])
    return subsets

def count_primes(numbers):
