        if n < 2:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    return sum(1 for num in numbers if is_prime(num))

def is_palindrome(s):
    s = ''.join(c for c in s if c.isalpha()).lower()
    return s == s[::-1]

from typing import Dict, Optional

def first_char_with_count(s: str, n: int) -> Optional[str]:
    """Returns the first character in s that occurs exactly n times.

    Args:
        s: The input string containing lowercase letters and digits.
        n: The target number of occurrences.

    Returns:
        The first character with exactly n occurrences, or None if no such character exists.
    """
    counts: Dict[str, int] = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1
    for char in s:
        if counts[char] == n:
            return char
    return None
